--
-- Table structure for table `access_reviews`
--

DROP TABLE IF EXISTS `access_reviews`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `access_reviews` (
  `id` int NOT NULL AUTO_INCREMENT,
  `app_name` varchar(100) NOT NULL,
  `review_date` date NOT NULL,
  `review_content` text NOT NULL,
  `country_name` varchar(100) DEFAULT NULL,
  `rating` int DEFAULT NULL,
  `store_name` varchar(255) DEFAULT NULL,
  `earned_by` varchar(255) DEFAULT NULL,
  `original_review_id` int NOT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_review` (`original_review_id`),
  KEY `idx_app_name` (`app_name`),
  KEY `idx_review_date` (`review_date`),
  KEY `idx_earned_by` (`earned_by`),
  CONSTRAINT `fk_access_reviews_original` FOREIGN KEY (`original_review_id`) REFERENCES `reviews` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=9108 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

